      { "@type": "City", "name": "Tokyo" }
    ],
    "sameAs": [
      "https://www.linkedin.com/company/globalstone",
      "https://twitter.com/globalstone"
    ]
  }
  </script>

  <style>
    /* ===== RESET & BASE ===== */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; }
    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      color: #1A1A2E;
      background: #fff;
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }
    img { max-width: 100%; display: block; }
    a { text-decoration: none; color: inherit; }
    ul { list-style: none; }

    /* ===== VARIABLES ===== */
    :root {
      --navy: #0A1628;
      --navy-light: #121F36;
      --teal: #012A2D;
      --teal-mid: #00897B;
      --gold: #C9A84C;
      --gold-light: #D4B96A;
      --white: #FFFFFF;
      --gray-50: #F8F9FA;
      --gray-100: #F1F3F5;
      --gray-200: #E9ECEF;
      --gray-300: #DEE2E6;
      --gray-400: #ADB5BD;
      --gray-500: #6C757D;
      --gray-600: #495057;
      --gray-700: #343A40;
      --gray-800: #212529;
      --max-width: 1200px;
      --serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
      --sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    }

    /* ===== UTILITY ===== */
    .container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }

    /* ===== HEADER ===== */
    .header {
      position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
      background: var(--navy);
      height: 72px;
      transition: background 0.3s, box-shadow 0.3s;
    }
    .header.scrolled { background: rgba(10,22,40,0.97); box-shadow: 0 2px 20px rgba(0,0,0,0.3); }
    .header-inner {
      display: flex; align-items: center; justify-content: space-between;
      height: 72px;
    }
    .logo {
      font-family: var(--serif); font-size: 24px; font-weight: 700;
      color: var(--white); letter-spacing: -0.5px;
    }
    .logo span { color: var(--gold); }

    /* Desktop Nav */
    .nav-desktop { display: flex; align-items: center; gap: 0; }
    .nav-desktop > li { position: relative; }
    .nav-desktop > li > a {
      display: flex; align-items: center; gap: 4px;
      padding: 0 18px; height: 72px;
      color: rgba(255,255,255,0.85); font-size: 14px; font-weight: 500;
      letter-spacing: 0.3px; text-transform: uppercase;
      transition: color 0.2s;
    }
    .nav-desktop > li > a:hover { color: var(--white); }
    .nav-desktop > li > a .arrow {
      width: 0; height: 0; border-left: 4px solid transparent;
      border-right: 4px solid transparent; border-top: 4px solid currentColor;
      margin-top: 2px; transition: transform 0.2s;
    }
    .nav-desktop > li:hover > a .arrow { transform: rotate(180deg); }

    /* Mega Menu */
    .mega-menu {
      position: absolute; top: 72px; left: 50%; transform: translateX(-50%);
      width: 680px; background: var(--white);
      border-radius: 0 0 8px 8px;
      box-shadow: 0 20px 60px rgba(0,0,0,0.2);
      padding: 32px 36px;
      display: none; opacity: 0;
      transition: opacity 0.25s;
    }
    .nav-desktop > li:hover .mega-menu,
    .nav-desktop > li.mega-open .mega-menu {
      display: grid; grid-template-columns: 1fr 1fr; gap: 28px; opacity: 1;
    }
    .mega-col h4 {
      font-family: var(--sans); font-size: 11px; font-weight: 700;
      text-transform: uppercase; letter-spacing: 1.5px;
      color: var(--gray-500); margin-bottom: 14px;
      padding-bottom: 10px; border-bottom: 1px solid var(--gray-200);
    }
    .mega-col ul li a {
      display: block; padding: 8px 0; font-size: 14px;
      color: var(--gray-700); font-weight: 400;
      transition: color 0.2s, padding-left 0.2s;
    }
    .mega-col ul li a:hover {
      color: var(--teal-mid); padding-left: 6px;
    }

    /* Mobile Toggle */
    .mobile-toggle {
      display: none; background: none; border: none; cursor: pointer; padding: 8px;
    }
    .mobile-toggle span {
      display: block; width: 24px; height: 2px;
      background: var(--white); margin: 5px 0;
      transition: all 0.3s;
    }
    .mobile-toggle.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
    .mobile-toggle.active span:nth-child(2) { opacity: 0; }
    .mobile-toggle.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

    /* Mobile Nav */
    .nav-mobile {
      display: none; position: fixed; top: 72px; left: 0; right: 0; bottom: 0;
      background: var(--navy); overflow-y: auto; padding: 20px 0;
      z-index: 999;
    }
    .nav-mobile.active { display: block; }
    .nav-mobile .mobile-item { border-bottom: 1px solid rgba(255,255,255,0.08); }
    .nav-mobile .mobile-item > a {
      display: flex; justify-content: space-between; align-items: center;
      padding: 16px 24px; color: rgba(255,255,255,0.9);
      font-size: 16px; font-weight: 500;
    }
    .nav-mobile .mobile-item > a .arrow-sm {
      width: 8px; height: 8px; border-right: 1.5px solid currentColor;
      border-bottom: 1.5px solid currentColor; transform: rotate(45deg);
      transition: transform 0.3s;
    }
    .nav-mobile .mobile-item.open > a .arrow-sm { transform: rotate(-135deg); }
    .nav-mobile .mobile-sub {
      display: none; padding: 0 24px 16px 36px;
    }
    .nav-mobile .mobile-item.open .mobile-sub { display: block; }
    .nav-mobile .mobile-sub h5 {
      font-size: 10px; text-transform: uppercase; letter-spacing: 1.5px;
      color: var(--gold); margin: 12px 0 8px; font-weight: 600;
    }
    .nav-mobile .mobile-sub a {
      display: block; padding: 8px 0; font-size: 14px;
      color: rgba(255,255,255,0.7);
    }
    .nav-mobile .mobile-sub a:hover { color: var(--white); }

    /* ===== HERO ===== */
    .hero {
      position: relative; min-height: 85vh;
      display: flex; align-items: center;
      background: linear-gradient(135deg, var(--navy) 0%, #0D1F3C 50%, var(--teal) 100%);
      padding-top: 72px; overflow: hidden;
    }
    .hero::before {
      content: ''; position: absolute; inset: 0;
      background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 800"><rect fill="%230A1628" width="1200" height="800"/><g opacity="0.05"><rect x="100" y="200" width="80" height="400" fill="white" rx="4"/><rect x="220" y="150" width="60" height="500" fill="white" rx="4"/><rect x="320" y="180" width="100" height="420" fill="white" rx="4"/><rect x="460" y="120" width="70" height="480" fill="white" rx="4"/><rect x="560" y="200" width="90" height="400" fill="white" rx="4"/><rect x="680" y="160" width="60" height="440" fill="white" rx="4"/><rect x="780" y="190" width="110" height="410" fill="white" rx="4"/><rect x="920" y="140" width="80" height="460" fill="white" rx="4"/><rect x="1030" y="170" width="70" height="430" fill="white" rx="4"/></g></svg>') center/cover no-repeat;
      opacity: 0.4;
    }
    .hero-content {
      position: relative; z-index: 2; max-width: 680px;
    }
    .hero-label {
      display: inline-block; font-size: 12px; font-weight: 600;
      text-transform: uppercase; letter-spacing: 2px;
      color: var(--gold); margin-bottom: 20px;
    }
    .hero h1 {
      font-family: var(--serif); font-size: clamp(36px, 5vw, 56px);
      font-weight: 600; color: var(--white);
      line-height: 1.15; margin-bottom: 20px;
    }
    .hero p {
      font-size: 18px; color: rgba(255,255,255,0.8);
      line-height: 1.7; margin-bottom: 32px; max-width: 540px;
    }
    .btn-primary {
      display: inline-flex; align-items: center; gap: 8px;
      padding: 14px 32px; background: var(--gold);
      color: var(--navy); font-size: 14px; font-weight: 600;
      letter-spacing: 0.5px; border: none; cursor: pointer;
      transition: background 0.3s, transform 0.2s;
    }
    .btn-primary:hover { background: var(--gold-light); transform: translateY(-1px); }
    .btn-secondary {
      display: inline-flex; align-items: center; gap: 8px;
      padding: 14px 32px; background: transparent;
      color: var(--white); font-size: 14px; font-weight: 600;
      letter-spacing: 0.5px; border: 1.5px solid rgba(255,255,255,0.4);
      cursor: pointer; transition: all 0.3s;
    }
    .btn-secondary:hover { border-color: var(--white); background: rgba(255,255,255,0.08); }

    /* ===== FEATURED INSIGHTS ===== */
    .section { padding: 80px 0; }
    .section-dark { background: var(--navy); color: var(--white); }
    .section-light { background: var(--gray-50); }
    .section-header {
      margin-bottom: 48px;
    }
    .section-header h2 {
      font-family: var(--serif); font-size: clamp(28px, 3vw, 40px);
      font-weight: 600; margin-bottom: 12px;
    }
    .section-header p {
      font-size: 16px; color: var(--gray-500); max-width: 560px;
    }

    .insights-grid {
      display: grid; grid-template-columns: repeat(3, 1fr);
      gap: 28px;
    }
    .insight-card {
      background: var(--white); border-radius: 8px;
      overflow: hidden; box-shadow: 0 2px 16px rgba(0,0,0,0.06);
      transition: transform 0.3s, box-shadow 0.3s;
    }
    .insight-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.1); }
    .insight-card-img {
      height: 180px; background: linear-gradient(135deg, var(--teal), var(--navy));
      display: flex; align-items: center; justify-content: center;
      color: rgba(255,255,255,0.3); font-size: 48px;
    }
    .insight-card-body { padding: 24px; }
    .insight-tag {
      display: inline-block; font-size: 11px; font-weight: 600;
      text-transform: uppercase; letter-spacing: 1px;
      color: var(--teal-mid); margin-bottom: 10px;
    }
    .insight-card h3 {
      font-size: 17px; font-weight: 600; line-height: 1.4;
      margin-bottom: 12px; color: var(--gray-800);
    }
    .insight-card p {
      font-size: 14px; color: var(--gray-500); line-height: 1.6;
    }

    /* ===== ANNOUNCEMENT BANNER ===== */
    .announcement {
      background: linear-gradient(90deg, var(--teal) 0%, #004D40 100%);
      padding: 24px 0;
    }
    .announcement-inner {
      display: flex; align-items: center; justify-content: space-between;
      gap: 20px; flex-wrap: wrap;
    }
    .announcement-text {
      display: flex; align-items: center; gap: 12px;
      color: var(--white);
    }
    .announcement-badge {
      background: var(--gold); color: var(--navy);
      font-size: 10px; font-weight: 700; text-transform: uppercase;
      letter-spacing: 1px; padding: 4px 10px; border-radius: 3px;
    }
    .announcement-text p { font-size: 16px; font-weight: 500; }
    .btn-gold-outline {
      padding: 10px 24px; background: transparent;
      border: 1.5px solid var(--gold); color: var(--gold);
      font-size: 13px; font-weight: 600; letter-spacing: 0.3px;
      cursor: pointer; transition: all 0.3s; white-space: nowrap;
    }
    .btn-gold-outline:hover { background: var(--gold); color: var(--navy); }

    /* ===== ABOUT STATEMENT ===== */
    .about { padding: 80px 0; text-align: center; }
    .about h2 {
      font-family: var(--serif); font-size: clamp(24px, 2.5vw, 36px);
      font-weight: 500; max-width: 800px; margin: 0 auto 20px;
      line-height: 1.5; color: var(--gray-800);
    }
    .about p {
      font-size: 16px; color: var(--gray-500); max-width: 600px;
      margin: 0 auto 28px; line-height: 1.7;
    }
    .btn-teal {
      display: inline-flex; align-items: center; gap: 8px;
      padding: 12px 28px; background: var(--teal-mid);
      color: var(--white); font-size: 14px; font-weight: 600;
      border: none; cursor: pointer; transition: background 0.3s;
    }
    .btn-teal:hover { background: #00796B; }

    /* ===== WHAT WE DO (TABS) ===== */
    .whatwedo { padding: 80px 0; background: var(--gray-50); }
    .whatwedo-grid {
      display: grid; grid-template-columns: 260px 1fr;
      gap: 0; background: var(--white);
      border-radius: 8px; overflow: hidden;
      box-shadow: 0 4px 24px rgba(0,0,0,0.06);
      min-height: 380px;
    }
    .whatwedo-tabs {
      background: var(--navy); padding: 0;
    }
    .whatwedo-tab {
      display: flex; align-items: center; gap: 12px;
      padding: 24px 28px; width: 100%;
      background: none; border: none; cursor: pointer;
      color: rgba(255,255,255,0.6); font-size: 15px;
      font-family: var(--sans); font-weight: 500;
      text-align: left; transition: all 0.3s;
      border-left: 3px solid transparent;
    }
    .whatwedo-tab:hover { color: rgba(255,255,255,0.9); background: rgba(255,255,255,0.04); }
    .whatwedo-tab.active {
      color: var(--white); background: rgba(255,255,255,0.08);
      border-left-color: var(--gold);
    }
    .whatwedo-panel {
      padding: 48px 52px;
      display: none;
    }
    .whatwedo-panel.active { display: block; }
    .whatwedo-panel h3 {
      font-family: var(--serif); font-size: 28px; font-weight: 600;
      margin-bottom: 16px; color: var(--gray-800);
    }
    .whatwedo-panel p {
      font-size: 16px; color: var(--gray-600); line-height: 1.7;
      margin-bottom: 16px;
    }
    .whatwedo-panel ul {
      margin-bottom: 24px; padding-left: 0;
    }
    .whatwedo-panel ul li {
      padding: 6px 0; font-size: 15px; color: var(--gray-600);
      display: flex; align-items: center; gap: 8px;
    }
    .whatwedo-panel ul li::before {
      content: ''; width: 6px; height: 6px; border-radius: 50%;
      background: var(--gold); flex-shrink: 0;
    }

    /* ===== NEWSLETTER ===== */
    .newsletter {
      padding: 80px 0;
      background: linear-gradient(135deg, var(--navy) 0%, #0D1F3C 100%);
      color: var(--white); text-align: center;
    }
    .newsletter h2 {
      font-family: var(--serif); font-size: clamp(28px, 3vw, 36px);
      font-weight: 600; margin-bottom: 12px;
    }
    .newsletter p {
      font-size: 16px; color: rgba(255,255,255,0.7);
      margin-bottom: 28px; max-width: 480px; margin-left: auto; margin-right: auto;
    }
    .newsletter-form {
      display: flex; gap: 12px; max-width: 440px; margin: 0 auto;
    }
    .newsletter-form input {
      flex: 1; padding: 14px 18px; background: rgba(255,255,255,0.1);
      border: 1px solid rgba(255,255,255,0.2); border-radius: 4px;
      color: var(--white); font-size: 14px; font-family: var(--sans);
    }
    .newsletter-form input::placeholder { color: rgba(255,255,255,0.4); }
    .newsletter-form input:focus { outline: none; border-color: var(--gold); }

    /* ===== LATEST INSIGHTS ===== */
    .latest-grid {
      display: grid; grid-template-columns: repeat(3, 1fr);
      gap: 28px;
    }
    .latest-card {
      border-radius: 8px; overflow: hidden;
      background: var(--white); box-shadow: 0 2px 16px rgba(0,0,0,0.06);
      transition: transform 0.3s, box-shadow 0.3s;
    }
    .latest-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.1); }
    .latest-card-img {
      height: 160px; background: linear-gradient(135deg, #1a365d, var(--teal));
      display: flex; align-items: center; justify-content: center;
    }
    .latest-card-img span { color: rgba(255,255,255,0.3); font-size: 40px; }
    .latest-card-body { padding: 20px; }
    .latest-card .meta {
      font-size: 11px; text-transform: uppercase; letter-spacing: 1px;
      color: var(--teal-mid); font-weight: 600; margin-bottom: 8px;
    }
    .latest-card h3 {
      font-size: 16px; font-weight: 600; line-height: 1.4;
      margin-bottom: 10px; color: var(--gray-800);
    }
    .latest-card .date {
      font-size: 13px; color: var(--gray-400);
    }

    /* ===== COMMITMENT ===== */
    .commitment-grid {
      display: grid; grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }
    .commitment-card {
      padding: 36px 28px; background: var(--white);
      border-radius: 8px; border: 1px solid var(--gray-200);
      transition: border-color 0.3s, box-shadow 0.3s;
    }
    .commitment-card:hover {
      border-color: var(--gold); box-shadow: 0 4px 20px rgba(201,168,76,0.12);
    }
    .commitment-card h3 {
      font-family: var(--serif); font-size: 20px; font-weight: 600;
      margin-bottom: 12px; color: var(--gray-800);
    }
    .commitment-card p {
      font-size: 14px; color: var(--gray-500); line-height: 1.6;
      margin-bottom: 16px;
    }
    .commitment-card .link {
      font-size: 13px; font-weight: 600; color: var(--teal-mid);
      display: inline-flex; align-items: center; gap: 4px;
      transition: gap 0.2s;
    }
    .commitment-card:hover .link { gap: 8px; }

    /* ===== FOOTER ===== */
    .footer {
      background: var(--navy); color: rgba(255,255,255,0.6);
      padding: 64px 0 32px;
    }
    .footer-grid {
      display: grid; grid-template-columns: 2fr 1fr 1fr 1fr;
      gap: 48px; margin-bottom: 48px;
    }
    .footer-brand .logo { margin-bottom: 16px; font-size: 22px; }
    .footer-brand p { font-size: 14px; line-height: 1.7; max-width: 280px; }
    .footer h4 {
      font-size: 12px; font-weight: 700; text-transform: uppercase;
      letter-spacing: 1.5px; color: var(--white); margin-bottom: 16px;
    }
    .footer ul li a {
      display: block; padding: 4px 0; font-size: 14px;
      color: rgba(255,255,255,0.5); transition: color 0.2s;
    }
    .footer ul li a:hover { color: var(--white); }
    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.08);
      padding-top: 24px;
      display: flex; justify-content: space-between; align-items: center;
      flex-wrap: wrap; gap: 12px;
    }
    .footer-bottom p { font-size: 13px; }
    .footer-legal { display: flex; gap: 20px; flex-wrap: wrap; }
    .footer-legal a { font-size: 13px; color: rgba(255,255,255,0.4); }
    .footer-legal a:hover { color: var(--white); }

    /* ===== RESPONSIVE ===== */
    @media (max-width: 1024px) {
      .commitment-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-grid { grid-template-columns: 1fr 1fr; }
    }
    @media (max-width: 768px) {
      .nav-desktop { display: none; }
      .mobile-toggle { display: block; }
      .hero { min-height: 70vh; }
