  <script>
    // Header scroll effect
    const header = document.getElementById('header');
    window.addEventListener('scroll', () => {
      header.classList.toggle('scrolled', window.scrollY > 40);
    });

    // Mobile nav toggle
    const mobileToggle = document.getElementById('mobileToggle');
    const mobileNav = document.getElementById('mobileNav');
    mobileToggle.addEventListener('click', () => {
      mobileToggle.classList.toggle('active');
      mobileNav.classList.toggle('active');
      document.body.style.overflow = mobileNav.classList.contains('active') ? 'hidden' : '';
    });

    // Mobile accordion
    document.querySelectorAll('.nav-mobile .mobile-item > a').forEach(a => {
      a.addEventListener('click', (e) => {
        const item = a.parentElement;
        if (item.querySelector('.mobile-sub')) {
          e.preventDefault();
          item.classList.toggle('open');
        }
      });
    });

    // What We Do tabs
    const tabs = document.querySelectorAll('.whatwedo-tab');
    const panels = document.querySelectorAll('.whatwedo-panel');
    tabs.forEach(tab => {
      tab.addEventListener('click', () => {
        tabs.forEach(t => t.classList.remove('active'));
        panels.forEach(p => p.classList.remove('active'));
        tab.classList.add('active');
        document.getElementById('panel-' + tab.dataset.tab).classList.add('active');
      });
    });

    // Mega menu click toggle for touch devices
    document.querySelectorAll('.nav-desktop > li').forEach(li => {
      const megaMenu = li.querySelector('.mega-menu');
      if (megaMenu) {
        li.querySelector('a').addEventListener('click', (e) => {
          if (window.innerWidth >= 769) {
            e.preventDefault();
            li.classList.toggle('mega-open');
          }
        });
      }
    });
    // Close mega menu on outside click
    document.addEventListener('click', (e) => {
      if (!e.target.closest('.nav-desktop > li')) {
        document.querySelectorAll('.nav-desktop > li.mega-open').forEach(li => {
          li.classList.remove('mega-open');
        });
      }
    });
  </script>
